function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
}

function renderFoodCards() {
  const grid = document.getElementById('foodGrid');
  if (!grid) return;
  grid.innerHTML = FOOD_CARDS.map(food => `
    <article class="food-card">
      <div class="food-img">
        ${food.image ? `<img src="${esc(food.image)}" alt="${esc(food.name)}" loading="lazy">` : '<div class="placeholder" aria-hidden="true">🍔</div>'}
      </div>
      <div class="food-body">
        ${food.badge ? `<span class="badge">${esc(food.badge)}</span>` : ''}
        <h3>${esc(food.name)}</h3>
        <div class="food-price">${esc(food.price)}</div>
        <p class="food-desc">${esc(food.shortDescription)}</p>
        <p class="food-details">${esc(food.details)}</p>
        <div class="food-actions">
          <a class="small" href="https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent('سلام حسن برګر، درباره «'+food.name+'» معلومات می‌خواهم.')}" target="_blank" rel="noopener">💬 WhatsApp</a>
        </div>
      </div>
    </article>`).join('');
}

function toast(message) {
  const el = document.getElementById('toast');
  if (!el) return;
  el.textContent = message;
  el.classList.add('show');
  setTimeout(() => el.classList.remove('show'), 2200);
}

function setLanguage(lang) {
  const dict = T[lang] || T.ps;
  document.documentElement.lang = lang;
  document.documentElement.dir = lang === 'en' ? 'ltr' : 'rtl';
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.dataset.i18n;
    if (dict[key]) el.textContent = dict[key];
  });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.dataset.i18nPlaceholder;
    if (dict[key]) el.placeholder = dict[key];
  });
  document.querySelectorAll('[data-lang]').forEach(btn => btn.classList.toggle('active', btn.dataset.lang === lang));
  localStorage.setItem('hbLang', lang);
}

document.addEventListener('DOMContentLoaded', () => {
  renderFoodCards();
  setLanguage(localStorage.getItem('hbLang') || 'ps');

  document.querySelectorAll('[data-lang]').forEach(btn => btn.addEventListener('click', () => setLanguage(btn.dataset.lang)));

  const navToggle = document.getElementById('menuToggle');
  const nav = document.getElementById('navlinks');
  navToggle?.addEventListener('click', () => nav?.classList.toggle('open'));
  document.querySelectorAll('#navlinks a').forEach(a => a.addEventListener('click', () => nav?.classList.remove('open')));

  document.getElementById('copyAddress')?.addEventListener('click', async () => {
    try { await navigator.clipboard.writeText(ADDRESS); toast('آدرس کاپی شد'); }
    catch { toast(ADDRESS); }
  });

  document.getElementById('sendWhatsApp')?.addEventListener('click', () => {
    const input = document.getElementById('waMessage');
    const message = input?.value.trim();
    if (!message) { toast('لطفاً پیام خود را بنویسید'); input?.focus(); return; }
    window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(message)}`, '_blank', 'noopener');
  });

  const modal = document.getElementById('modal');
  const modalImg = document.getElementById('modalImg');
  document.querySelectorAll('.gallery img, #menuImage').forEach(img => img.addEventListener('click', () => {
    if (!modal || !modalImg) return;
    modalImg.src = img.src; modalImg.alt = img.alt; modal.classList.add('open');
  }));
  document.getElementById('closeModal')?.addEventListener('click', () => modal?.classList.remove('open'));
  modal?.addEventListener('click', e => { if (e.target === modal) modal.classList.remove('open'); });
});
